d":{"title":"ExternalAccountId","type":"string","minLength":1,"maxLength":64,"pattern":"^[a-z0-9](?:[a-z0-9-]{0,62}[a-z0-9])?\$","description":"The identifier of an external account held by the community\'s VTA (the external/accounts/* family), which issues the community short-lived, room-scoped credentials and holds the long-lived authority itself."},"StorageSettings":{"title":"StorageSettings","description":"A config\'s backend settings, discriminated by `kind`. Never a secret: a credential is a StorageAuth, held elsewhere.","oneOf":[{"\$ref":"#/\$defs/LocalSettings"},{"\$ref":"#/\$defs/S3Settings"},{"\$ref":"#/\$defs/GcsSettings"},{"\$ref":"#/\$defs/WalrusSettings"}]},"WalrusSettings":{"title":"WalrusSettings","type":"object","additionalProperties":false,"required":["kind","relayUrl","aggregatorUrl","epochs","extendBeforeEpochs"],"properties":{"kind":{"const":"walrus"},"relayUrl":{"type":"string","format":"uri","maxLength":2048,"pattern":"^https://","description":"The Walrus upload relay the community writes through. The community never runs a publisher: a publisher holds a hot wallet in its own configuration, which is the long-lived secret these tasks exist to avoid."},"aggregatorUrl":{"type":"string","format":"uri","maxLength":2048,"pattern":"^https://","description":"The Walrus aggregator the community reads through."},"epochs":{"type":"integer","minimum":1,"maximum":53,"description":"Storage epochs to buy when a blob is registered. Walrus sells storage in epochs (two weeks on mainnet) and caps one purchase at 53."},"extendBeforeEpochs":{"type":"integer","minimum":1,"maximum":52,"description":"How many epochs before a live blob\'s end epoch the community extends it. A blob that has become an orphan is not extended, and lapses: the Walrus form of deletion."}}},"GcsSettings":{"title":"GcsSettings","type":"object","additionalProperties":false,"required":["kind","bucket"],"properties":{"kind":{"const":"gcs"},"bucket":{"type":"string","minLength":3,"maxLength":222,"pattern":"^[a-z0-9][a-z0-9._-]{1,220}[a-z0-9]\$","description":"The bucket name. Validated against GCS naming rules here, because it is placed in a Credential Access Boundary condition and must never carry anything but a name."},"prefix":{"\$ref":"#/\$defs/ObjectPrefix"}}},"ObjectPrefix":{"title":"ObjectPrefix","type":"string","minLength":1,"maxLength":256,"pattern":"^[A-Za-z0-9!_.*\'()/-]+/\$","description":"A key prefix inside the bucket, ending in `/`, under which the config\'s `rooms/` tree is placed. Restricted to the S3 safe-character set so that it can be placed in a downscoped policy without escaping."},"S3Settings":{"title":"S3Settings","type":"object","additionalProperties":false,"required":["kind","region","bucket"],"properties":{"kind":{"const":"s3"},"endpoint":{"type":"string","format":"uri","maxLength":2048,"pattern":"^https://","description":"The S3 API endpoint, for a store other than AWS (R2, B2, MinIO). Absent means AWS S3 in `region`. HTTPS only."},"region":{"type":"string","minLength":1,"maxLength":64,"pattern":"^[a-z0-9-]+\$","description":"The bucket\'s region, as the store names it (`eu-west-1`; `auto` for R2)."},"bucket":{"type":"string","minLength":3,"maxLength":63,"pattern":"^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]\$","description":"The bucket name. Validated against S3 naming rules here, because it is placed in downscoped session policies and must never carry anything but a name."},"prefix":{"\$ref":"#/\$defs/ObjectPrefix"},"pathStyle":{"type":"boolean","description":"Address the bucket in the path rather than the host name, as MinIO usually needs. Absent means virtual-hosted style."}}},"LocalSettings":{"title":"LocalSettings","type":"object","additionalProperties":false,"required":["kind","root"],"properties":{"kind":{"const":"local"},"root":{"type":"string","minLength":1,"maxLength":1024,"pattern":"^/","description":"Absolute path of the directory the community writes blobs under, on its own host. Created owner-only. Not carried by the community\'s backup: back it up beside it."}}},"StorageConfigId":{"title":"StorageConfigId","type":"string","minLength":1,"maxLength":64,"pattern":"^[a-z0-9](?:[a-z0-9-]{0,62}[a-z0-9])?\$","description":"A storage config\'s identifier, chosen by the administrator who creates it and immutable thereafter: lowercase letters, digits and inner hyphens, at most 64 characters (`eu-s3-primary`, `walrus-main`). Unique within the community. Never reused after a config is retired, because blobs name their config by this value."}}}';

/// The SPEC §7.2 policy for the request variant, taken from this
/// specification's front matter.
///
/// Pass it to [consumeInbound] — items 5b, 7 and 8 are per-specification and
/// cannot be derived from the document alone, and item 2 needs the schema it
/// carries.
const SpecPolicy spec = SpecPolicy(
  typeUri: typeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: payloadSchemaJson,
);

/// The SPEC §7.2 policy for the success-response variant.
///
/// `isRecipientRequired` tracks the *issuer* party's requirement, because a
/// response swaps the parties (§7.3 item 5).
const SpecPolicy responseSpec = SpecPolicy(
  typeUri: responseTypeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: responsePayloadSchemaJson,
);
